-- 上記で表されていないチップセットについては、他の文書で -- OBJECT IDENTIFIERを割り当てる必要がある。たとえば、
-- 個々の企業に委任された登録木の部分の中での割り当て -- （RFC 1155とRFC 1902を参照）である。 -- -- -- 将来、チップセットの登録の管理はInternet Assigned Numbers -- Authority（IANA）に委任される可能性がある。
-- 適合性情報
etherConformance OBJECT IDENTIFIER ::= { etherMIB 2 }
etherGroups OBJECT IDENTIFIER ::= { etherConformance 1 } etherCompliances OBJECT IDENTIFIER ::= { etherConformance 2 }
-- 適合性記述
etherCompliance MODULE-COMPLIANCE STATUS current DESCRIPTION "The compliance statement for managed network entities which have ethernet-like network interfaces."
MODULE -- このモジュール MANDATORY-GROUPS { etherStatsGroup }
GROUP etherCollisionTableGroup DESCRIPTION "This group is optional. It is appropriate for all systems which have the necessary metering. Implementation in such systems is highly recommended." ::= { etherCompliances 1 }
ether100MbsCompliance MODULE-COMPLIANCE STATUS current DESCRIPTION "The compliance statement for managed network entities which have 100 Mb/sec ethernet-like network interfaces."
MODULE -- このモジュール MANDATORY-GROUPS { etherStats100MbsGroup }
GROUP etherCollisionTableGroup DESCRIPTION "This group is optional. It is appropriate for all systems which have the necessary metering. Implementation in such systems is highly recommended." ::= { etherCompliances 2 }
-- 適合性の単位
etherStatsGroup OBJECT-GROUP OBJECTS { dot3StatsIndex, dot3StatsAlignmentErrors, dot3StatsFCSErrors, dot3StatsSingleCollisionFrames, dot3StatsMultipleCollisionFrames, dot3StatsSQETestErrors, dot3StatsDeferredTransmissions, dot3StatsLateCollisions, dot3StatsExcessiveCollisions, dot3StatsInternalMacTransmitErrors, dot3StatsCarrierSenseErrors, dot3StatsFrameTooLongs, dot3StatsInternalMacReceiveErrors, dot3StatsEtherChipSet } STATUS current DESCRIPTION "A collection of objects providing information applicable to all ethernet-like network interfaces." ::= { etherGroups 1 }
etherCollisionTableGroup OBJECT-GROUP OBJECTS { dot3CollFrequencies } STATUS current DESCRIPTION "A collection of objects providing a histogram of packets successfully transmitted after experiencing exactly N collisions." ::= { etherGroups 2 }
etherStats100MbsGroup OBJECT-GROUP OBJECTS { dot3StatsIndex, dot3StatsAlignmentErrors, dot3StatsFCSErrors, dot3StatsSingleCollisionFrames, dot3StatsMultipleCollisionFrames, dot3StatsDeferredTransmissions, dot3StatsLateCollisions, dot3StatsExcessiveCollisions, dot3StatsInternalMacTransmitErrors, dot3StatsCarrierSenseErrors, dot3StatsFrameTooLongs, dot3StatsInternalMacReceiveErrors, dot3StatsEtherChipSet, dot3StatsSymbolErrors } STATUS current DESCRIPTION "A collection of objects providing information applicable to 100 Mb/sec ethernet-like network interfaces." ::= { etherGroups 3 }
END
